import{_ as a,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"30、【離】 離下離上","description":"周易闡真 - 30、【離】 離下離上","frontmatter":{"title":"30、【離】 離下離上","description":"周易闡真 - 30、【離】 離下離上"},"headers":[],"relativePath":"classics/chanzhen/031.md","filePath":"classics/chanzhen/031.md"}'),s={name:"classics/chanzhen/031.md"};function n(c,p,i,o,l,h){return t(),e("div",null,[...p[0]||(p[0]=[r('<blockquote><p>彖曰：離，麗也。日月麗乎天，百穀草木麗乎土。重明以麗乎正，乃化成天下。柔麗乎中正，故亨，是以畜牝牛吉也。</p></blockquote><h1 id="_30、【離】-離下離上" tabindex="-1">30、【離】 離下離上 <a class="header-anchor" href="#_30、【離】-離下離上" aria-label="Permalink to “30、【離】 離下離上”">​</a></h1><p>初九：履錯然，敬之，無咎。</p><p>六二：黃離，元吉。</p><p>九三：日昃之離，不鼓缶而歌，則大耋之嗟，兇。</p><p>九四：突如其來如，焚如，死如，棄如。</p><p>六五：出涕沱若，戚嗟若，吉。</p><p>上九：王用出徵，有嘉，折首，獲匪其醜，無咎。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：明兩作，離。大人以繼明照於四方。</p><p>離者，日明之謂。上離日，下離日，日之運用，夜則入地而內明，晝則出地而外明，一明而有兩作，此離之象也。</p><p>大人有見於此，知人不能明內，則必不能明外，先明內，後明外，明內如是，明外亦如是。以是明內已畢，又繼其明而照於四方也。明者，明內也；繼明者，又明外也。明者何明，即明其本來一點虛靈不昧之德耳。能虛能靈，內德已明，誠於中而達於外，無物能瞞，無事有累，照於四方，如在掌上，大地裡黃芽長遍，滿世界金花開綻，左之右之，頭頭是道，內外通徹，其明不息，方且自明明德而止於至善矣。但繼明照四方，非是空空無為即便了事，其中有增減之功。曰明照者，以明而照也。明不能照於四方，其明不大，不為繼明。既明內，又明外，明而必如日升虛空，下照萬物，萬物莫能蔽其明，方是真明，方是繼明。若稍有些子照不到，即有些子蔽其明。明能照於四方，縱橫逆順，皆不礙其照，無處不通，無處有傷，明明德之功盡矣。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>畜，昌六反。昃，音仄。耋，音咥。突，同忽反。</p><p>離者，麗也，明也。卦體一陰附麗於二陽之中，虛中能明之象。卦德上離明，下離明，由此明而及彼明，由彼明而達此明，明內而又明外，內明而又外明。千明萬明，總是兩明，內明外明，總是一明，故謂離。此雄裡懷雌、陽中有陰之卦，承上大過而來。</p><p>大過者，陽剛太過，雄而不雌，任心造化，誤用其明矣。明者，離宮虛靈之氣，為人之神，心之主。心虛則靈，元神主事，明而得正，能以濟陽。心亂則迷，識神主事，明而不當，足以傷陽，是以離利於貞而亨也。然雖離利於貞而亨，若只知用明，不知養明，亦不得亨。</p><p>夫用明者，外明也；養明者，內明也。外明必本於內明，用明須當先養明，是以又畜牝牛吉也。</p><p>畜者，養也。牛者，順象。牛至於牝，絕不用剛，其性至順，人能以柔順養明，雌而不雄，回光反照，閒邪存誠，先明內而後明外，內外俱明，虛靈不昧，無一物能瞞，無一物能移。自明明德而止於至善，其吉為何如乎！</p><p>但明而致吉之道，有火候，有工程，稍有不謹，明而不亨，故明必至於內外，無一不明，無一不正，方是明之利、明之亨、明之吉也。</p><p>初九，在明之初，不知養明，而即用明，履必錯然也。錯然之履，不但不能進明，而且有以傷明，惟敬之、博學之、審問之、慎思之、明辨之，自始自終，瞭然於心，而後篤行之，方無錯然之咎矣。此用明須當先求明者也。</p><p>六二，自知不明，而能虛心下賢求人之明，是謂黃離也。黃為中色，明而歸中，示己之無，尊人之有，雖愚必明，雖柔必強，不失其柔順之本質，其吉在於能虛心矣。此不明而求人之明者也。</p><p>九三，獨剛不柔，只知用明，不知養明，剛明太過，如日昃過缶之明，高極必下，明極必暗，是不能鼓缶而歌，則有大耋之嗟，不中不和，適以取兇而已。此用明而自敗其明者也。</p><p>九四，剛而不正，不能明內，即欲明外，是突如其來如也。突來之明，躐等而求，性躁行偏，妄作招兇，焚如，死如，棄如，欲求長生，反而傷命。此不明而自以為明者也。</p><p>六五，居外明之中，所當明內而又明外者，乃懦弱無能，或見理不真，或力有不及，是以出涕沱若，戚嗟若也。然涕沱戚嗟，不敢妄作妄為，自守本分，亦致吉之道。此明而知己不明者也。</p><p>上九，居重明之上，剛而有為，既能明內，又能明外，既能明順，又能明逆，取象王用出徵，有嘉折首，獲匪其醜也。</p><p>人之真心，如王明明德，如出征，明德而德即明，如有嘉功，除去人心，如折首惡，不強制雜念，如不獲從醜，用明而至折首之明，則後天一切客氣，不退而自化，寂然不動，感而遂通，內外光明，而無一毫根塵之咎矣。此明而至善無惡者也。</p><p>然則用明之道，須要知雄守雌，剛中有柔，明而得正為貴乎。倘有剛無柔，不落於突如其來，即歸於日昃之離，不但不能增明，而反有以傷明。修道者，欲用其明，可不先養其明乎！</p>',27)])])}const m=a(s,[["render",n]]);export{d as __pageData,m as default};
